using System;
using System.Globalization;
using System.IO;
using NUnit.Framework;
using UnityEditor;
using UnityEngine;

namespace CleanMyRoom.Tests
{
    /// <summary>
    /// EditMode import tests for the OBJ/MTL files generated by MATLAB Issue #010.
    ///
    /// The mesh files are produced by MATLAB/Graphics/demoProjectionExport.m into
    /// Shared_Data/Meshes/Issue010. This test copies them into a temporary Assets
    /// folder, imports them with Unity's real ModelImporter, and verifies the
    /// dimensions, orientation and coordinate conventions.
    ///
    /// Observed Unity behaviour (recorded in
    /// Deliverables/Reports/Issue010_Unity_Import_Result.txt):
    ///   - Unity's OBJ importer mirrors X to convert right-handed OBJ to Unity's
    ///     left-handed system. A file with x in [0, 2] is imported with x in
    ///     [-2, 0], so the bounds centre is [-1, 3, 2] rather than [1, 3, 2].
    ///     The size is unchanged and this is expected, not an export defect.
    ///   - MTL Kd is interpreted as linear colour; Material.color returns the
    ///     display (sRGB) value, e.g. Kd 0.2 becomes approximately 0.4845.
    ///   - The Unity Y-up variant imports with size [2, 5, 3]; the raw MATLAB
    ///     Z-up variant imports with size [2, 3, 5], which is why the Unity
    ///     remap is required for correct height in the game.
    /// </summary>
    public sealed class MeshImportTests
    {
        private const string ImportFolder = "Assets/Issue010ImportTest";
        private const string MatlabObj = "Issue010_Box_MATLAB.obj";
        private const string UnityObj = "Issue010_Box_Unity.obj";

        private string sourceFolder;

        [SetUp]
        public void SetUp()
        {
            string projectRoot = Path.GetFullPath(
                Path.Combine(Application.dataPath, "..", "..", ".."));
            sourceFolder = Path.Combine(projectRoot, "Shared_Data", "Meshes", "Issue010");

            Assert.IsTrue(Directory.Exists(sourceFolder),
                "MATLAB export folder not found: " + sourceFolder);

            Directory.CreateDirectory(Path.Combine(Application.dataPath, "Issue010ImportTest"));
            foreach (string variant in new[] { "MATLAB", "Unity" })
            {
                foreach (string extension in new[] { ".obj", ".mtl" })
                {
                    string name = "Issue010_Box_" + variant + extension;
                    string source = Path.Combine(sourceFolder, name);
                    Assert.IsTrue(File.Exists(source), "Missing export file: " + source);
                    File.Copy(source,
                        Path.Combine(Application.dataPath, "Issue010ImportTest", name), true);
                }
            }

            AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
        }

        [TearDown]
        public void TearDown()
        {
            AssetDatabase.DeleteAsset(ImportFolder);
            AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
        }

        [Test]
        public void UnityVariantImportsWithDocumentedDimensionsAndOrientation()
        {
            Mesh mesh = LoadMesh(UnityObj);
            Bounds bounds = mesh.bounds;

            Assert.AreEqual(2f, bounds.size.x, 1e-4f, "Unity X width must be 2.");
            Assert.AreEqual(5f, bounds.size.y, 1e-4f, "Unity Y height must be 5.");
            Assert.AreEqual(3f, bounds.size.z, 1e-4f, "Unity Z depth must be 3.");

            // The importer mirrors X (right-handed -> left-handed Unity).
            Assert.AreEqual(-1f, bounds.center.x, 1e-4f, "Mirrored X centre must be -1.");
            Assert.AreEqual(3f, bounds.center.y, 1e-4f, "Unity Y centre must be 3.");
            Assert.AreEqual(2f, bounds.center.z, 1e-4f, "Unity Z centre must be 2.");

            TestContext.WriteLine("Imported Unity bounds: centre " +
                Format(bounds.center) + ", size " + Format(bounds.size));
        }

        [Test]
        public void MatlabVariantKeepsZUpDimensions()
        {
            Mesh mesh = LoadMesh(MatlabObj);
            Bounds bounds = mesh.bounds;

            // Without the MATLAB -> Unity remap, height 5 stays on Z and the
            // imported object has height 3 in Unity's up (Y) axis.
            Assert.AreEqual(2f, bounds.size.x, 1e-4f);
            Assert.AreEqual(3f, bounds.size.y, 1e-4f);
            Assert.AreEqual(5f, bounds.size.z, 1e-4f);
        }

        [Test]
        public void ImportsAllVerticesTrianglesAndNormals()
        {
            Mesh mesh = LoadMesh(UnityObj);

            Assert.AreEqual(8, mesh.vertexCount, "Cube must have 8 exported vertices.");
            Assert.AreEqual(36, mesh.triangles.Length,
                "12 exported triangles must produce 36 triangle indices.");
            Assert.AreEqual(mesh.vertexCount, mesh.normals.Length,
                "Every exported vertex must have a normal.");

            // The box is convex: every outward normal must point away from
            // the centre. A negative value would mean reversed winding.
            Vector3 centre = mesh.bounds.center;
            float minimumDot = float.MaxValue;
            for (int i = 0; i < mesh.vertexCount; i++)
            {
                Vector3 radial = mesh.vertices[i] - centre;
                minimumDot = Mathf.Min(minimumDot,
                    Vector3.Dot(mesh.normals[i], radial.normalized));
            }
            Assert.Greater(minimumDot, 0.5f,
                "Imported normals must point outwards after the axis remap.");
        }

        [Test]
        public void ImportsDocumentedPhongMaterial()
        {
            GameObject model = LoadModel(UnityObj);
            var renderer = model.GetComponentInChildren<MeshRenderer>();
            Assert.IsNotNull(renderer, "Imported model must have a MeshRenderer.");

            var material = Array.Find(renderer.sharedMaterials,
                item => item != null && item.name == "CleanMyRoom_box");
            Assert.IsNotNull(material, "MTL material CleanMyRoom_box was not imported.");
            Assert.IsTrue(material.HasProperty("_Color"), "Material must expose _Color.");

            // Linear Kd 0.2, 0.55, 0.9 is returned as display/sRGB colour.
            Color expected = new Color(
                LinearToSrgb(0.2f), LinearToSrgb(0.55f), LinearToSrgb(0.9f), 1f);
            Assert.AreEqual(expected.r, material.color.r, 0.005f, "Red channel mismatch.");
            Assert.AreEqual(expected.g, material.color.g, 0.005f, "Green channel mismatch.");
            Assert.AreEqual(expected.b, material.color.b, 0.005f, "Blue channel mismatch.");
        }

        [Test]
        public void ObjFilesUseDocumentedAxisConventions()
        {
            Vector3 matlabSize = ReadSize(Path.Combine(sourceFolder, MatlabObj));
            Vector3 unitySize = ReadSize(Path.Combine(sourceFolder, UnityObj));

            Assert.AreEqual(new Vector3(2f, 3f, 5f), matlabSize,
                "MATLAB OBJ must keep Z-up bounds [2, 3, 5].");
            Assert.AreEqual(new Vector3(2f, 5f, 3f), unitySize,
                "Unity OBJ must remap to Y-up bounds [2, 5, 3].");
        }

        private static GameObject LoadModel(string fileName)
        {
            string assetPath = ImportFolder + "/" + fileName;
            AssetDatabase.ImportAsset(assetPath,
                ImportAssetOptions.ForceUpdate | ImportAssetOptions.ForceSynchronousImport);
            GameObject model = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
            Assert.IsNotNull(model, "Unity could not import " + assetPath);
            return model;
        }

        private static Mesh LoadMesh(string fileName)
        {
            GameObject model = LoadModel(fileName);
            var filter = model.GetComponentInChildren<MeshFilter>();
            Assert.IsNotNull(filter, "Imported model has no MeshFilter.");
            Assert.IsNotNull(filter.sharedMesh, "Imported model has no mesh.");
            return filter.sharedMesh;
        }

        private static Vector3 ReadSize(string path)
        {
            var minimum = new Vector3(float.MaxValue, float.MaxValue, float.MaxValue);
            var maximum = new Vector3(float.MinValue, float.MinValue, float.MinValue);
            foreach (string line in File.ReadAllLines(path))
            {
                if (!line.StartsWith("v ", StringComparison.Ordinal))
                {
                    continue;
                }
                string[] parts = line.Split(new[] { ' ' },
                    StringSplitOptions.RemoveEmptyEntries);
                var point = new Vector3(
                    float.Parse(parts[1], CultureInfo.InvariantCulture),
                    float.Parse(parts[2], CultureInfo.InvariantCulture),
                    float.Parse(parts[3], CultureInfo.InvariantCulture));
                minimum = Vector3.Min(minimum, point);
                maximum = Vector3.Max(maximum, point);
            }
            return maximum - minimum;
        }

        private static float LinearToSrgb(float value)
        {
            return value <= 0.0031308f
                ? 12.92f * value
                : 1.055f * Mathf.Pow(value, 1f / 2.4f) - 0.055f;
        }

        private static string Format(Vector3 value)
        {
            return string.Format(CultureInfo.InvariantCulture,
                "[{0:F4}, {1:F4}, {2:F4}]", value.x, value.y, value.z);
        }
    }
}
